from pathlib import Path
import re, zipfile, shutil
root=Path('/mnt/data/pizza_project')
s=root.joinpath('Dump20260919.sql').read_text(errors='ignore')
(root/'sql').mkdir(exist_ok=True)
(root/'database').mkdir(exist_ok=True)
(root/'screenshots').mkdir(exist_ok=True)
(root/'data').mkdir(exist_ok=True)

schema='''-- Pizza Hut Sales Analysis | Database Schema\n-- Source: Dump20260919.sql\n\nCREATE DATABASE IF NOT EXISTS pizzahut;\nUSE pizzahut;\n\nDROP TABLE IF EXISTS order_details;\nDROP TABLE IF EXISTS orders;\nDROP TABLE IF EXISTS pizzas;\nDROP TABLE IF EXISTS pizza_types;\n\nCREATE TABLE order_details (\n    order_detail_id INT NOT NULL,\n    order_id INT NOT NULL,\n    pizza_id TEXT NOT NULL,\n    quantity INT NOT NULL,\n    PRIMARY KEY (order_detail_id)\n);\n\nCREATE TABLE orders (\n    order_id INT NOT NULL,\n    order_date DATE NOT NULL,\n    order_time TIME NOT NULL,\n    PRIMARY KEY (order_id)\n);\n\nCREATE TABLE pizza_types (\n    pizza_type_id TEXT,\n    name TEXT,\n    category TEXT,\n    ingredients TEXT\n);\n\nCREATE TABLE pizzas (\n    pizza_id TEXT,\n    pizza_type_id TEXT,\n    size TEXT,\n    price DOUBLE DEFAULT NULL\n);\n'''
(root/'database'/'01_schema.sql').write_text(schema)

# Extract only INSERT statements, preserving source data exactly.
inserts=[]
for table in ['orders','order_details','pizza_types','pizzas']:
    for body in re.findall(r'INSERT INTO `'+re.escape(table)+r'` VALUES (.*?);',s,re.S):
        inserts.append(f"INSERT INTO `{table}` VALUES {body};\n")
(root/'database'/'02_load_data.sql').write_text('-- Pizza Hut Sales Analysis | Source Data Load\n-- Data extracted from Dump20260919.sql without changing values.\n\nUSE pizzahut;\n\n'+'\n'.join(inserts))

quality='''-- Pizza Hut Sales Analysis | Data Quality Checks\nUSE pizzahut;\n\n-- 1. Row counts\nSELECT 'orders' AS table_name, COUNT(*) AS row_count FROM orders\nUNION ALL SELECT 'order_details', COUNT(*) FROM order_details\nUNION ALL SELECT 'pizza_types', COUNT(*) FROM pizza_types\nUNION ALL SELECT 'pizzas', COUNT(*) FROM pizzas;\n\n-- 2. Date range in orders\nSELECT MIN(order_date) AS first_order_date, MAX(order_date) AS last_order_date\nFROM orders;\n\n-- 3. Orders without any order-detail records\nSELECT COUNT(*) AS orders_without_details\nFROM orders o\nLEFT JOIN order_details od ON o.order_id = od.order_id\nWHERE od.order_id IS NULL;\n\n-- 4. Order-detail rows whose pizza_id is not present in the pizza catalogue\nSELECT COUNT(*) AS orphan_pizza_ids\nFROM order_details od\nLEFT JOIN pizzas p ON od.pizza_id = p.pizza_id\nWHERE p.pizza_id IS NULL;\n\n-- 5. Pizza catalogue rows whose pizza_type_id is not present in pizza_types\nSELECT COUNT(*) AS orphan_pizza_type_ids\nFROM pizzas p\nLEFT JOIN pizza_types pt ON p.pizza_type_id = pt.pizza_type_id\nWHERE pt.pizza_type_id IS NULL;\n\n-- 6. Check for non-positive quantity values\nSELECT COUNT(*) AS invalid_quantities\nFROM order_details\nWHERE quantity <= 0;\n'''
(root/'sql'/'01_data_quality_checks.sql').write_text(quality)

analysis='''-- Pizza Hut Sales Analysis | Business Analysis Queries\nUSE pizzahut;\n\n-- 1. Total sales revenue (based on available order-detail records)\nSELECT ROUND(SUM(od.quantity * p.price), 2) AS total_revenue\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id;\n\n-- 2. Total pizzas sold\nSELECT SUM(quantity) AS total_pizzas_sold\nFROM order_details;\n\n-- 3. Orders with line-item data\nSELECT COUNT(DISTINCT order_id) AS orders_with_line_items\nFROM order_details;\n\n-- 4. Average order value for orders with line-item data\nSELECT ROUND(SUM(order_revenue) / COUNT(*), 2) AS average_order_value\nFROM (\n    SELECT od.order_id, SUM(od.quantity * p.price) AS order_revenue\n    FROM order_details od\n    JOIN pizzas p ON od.pizza_id = p.pizza_id\n    GROUP BY od.order_id\n) x;\n\n-- 5. Daily order volume\nSELECT o.order_date, COUNT(DISTINCT od.order_id) AS orders\nFROM orders o\nJOIN order_details od ON o.order_id = od.order_id\nGROUP BY o.order_date\nORDER BY o.order_date;\n\n-- 6. Monthly revenue\nSELECT DATE_FORMAT(o.order_date, '%Y-%m') AS month,\n       ROUND(SUM(od.quantity * p.price), 2) AS revenue\nFROM orders o\nJOIN order_details od ON o.order_id = od.order_id\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nGROUP BY DATE_FORMAT(o.order_date, '%Y-%m')\nORDER BY month;\n\n-- 7. Revenue by pizza category\nSELECT pt.category,\n       ROUND(SUM(od.quantity * p.price), 2) AS revenue\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nJOIN pizza_types pt ON p.pizza_type_id = pt.pizza_type_id\nGROUP BY pt.category\nORDER BY revenue DESC;\n\n-- 8. Revenue by pizza size\nSELECT p.size,\n       SUM(od.quantity) AS pizzas_sold,\n       ROUND(SUM(od.quantity * p.price), 2) AS revenue\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nGROUP BY p.size\nORDER BY revenue DESC;\n\n-- 9. Top 10 pizza types by revenue\nSELECT pt.name,\n       pt.category,\n       SUM(od.quantity) AS quantity_sold,\n       ROUND(SUM(od.quantity * p.price), 2) AS revenue\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nJOIN pizza_types pt ON p.pizza_type_id = pt.pizza_type_id\nGROUP BY pt.pizza_type_id, pt.name, pt.category\nORDER BY revenue DESC\nLIMIT 10;\n\n-- 10. Top 10 pizza types by quantity sold\nSELECT pt.name,\n       pt.category,\n       SUM(od.quantity) AS quantity_sold\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nJOIN pizza_types pt ON p.pizza_type_id = pt.pizza_type_id\nGROUP BY pt.pizza_type_id, pt.name, pt.category\nORDER BY quantity_sold DESC\nLIMIT 10;\n\n-- 11. Revenue by hour of day\nSELECT HOUR(o.order_time) AS order_hour,\n       COUNT(DISTINCT o.order_id) AS orders\nFROM orders o\nJOIN order_details od ON o.order_id = od.order_id\nGROUP BY HOUR(o.order_time)\nORDER BY order_hour;\n\n-- 12. Revenue by category as a percentage of available sales\nSELECT pt.category,\n       ROUND(SUM(od.quantity * p.price), 2) AS revenue,\n       ROUND(100 * SUM(od.quantity * p.price) /\n             (SELECT SUM(od2.quantity * p2.price)\n              FROM order_details od2 JOIN pizzas p2 ON od2.pizza_id = p2.pizza_id), 2) AS revenue_pct\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nJOIN pizza_types pt ON p.pizza_type_id = pt.pizza_type_id\nGROUP BY pt.category\nORDER BY revenue DESC;\n\n-- 13. Day-of-week order pattern\nSELECT DAYNAME(o.order_date) AS day_name,\n       COUNT(DISTINCT o.order_id) AS orders\nFROM orders o\nJOIN order_details od ON o.order_id = od.order_id\nGROUP BY DAYOFWEEK(o.order_date), DAYNAME(o.order_date)\nORDER BY DAYOFWEEK(o.order_date);\n\n-- 14. Highest-value individual order (available detail records)\nSELECT od.order_id,\n       ROUND(SUM(od.quantity * p.price), 2) AS order_value\nFROM order_details od\nJOIN pizzas p ON od.pizza_id = p.pizza_id\nGROUP BY od.order_id\nORDER BY order_value DESC\nLIMIT 10;\n'''
(root/'sql'/'02_business_analysis.sql').write_text(analysis)

readme='''# 🍕 Pizza Hut Sales Analysis — MySQL\n\nA portfolio-ready SQL project analyzing Pizza Hut order data using **MySQL**. The project focuses on relational joins, aggregations, time-based analysis, product performance, revenue analysis, and data-quality validation.\n\n## 🎯 Business Objective\n\nAnalyze available pizza-order data to understand sales performance, customer ordering patterns, product/category performance, and revenue contribution.\n\n## 🗂️ Dataset Structure\n\nThe supplied MySQL dump contains four tables:\n\n| Table | Purpose |\n|---|---|\n| `orders` | Order date and time |\n| `order_details` | Pizza items and quantities in each order |\n| `pizzas` | Pizza size and price |\n| `pizza_types` | Pizza name, category and ingredients |\n\n### Relationship used for analysis\n\n`orders` → `order_details` → `pizzas` → `pizza_types`\n\n## 🛠️ Tools & Skills\n\n- MySQL 8\n- SQL Joins\n- GROUP BY / HAVING\n- Aggregate functions\n- Subqueries\n- Date & time functions\n- CASE / conditional analysis\n- Data quality checks\n- Business KPI analysis\n\n## 📊 Analysis Included\n\n1. Total revenue\n2. Total pizzas sold\n3. Orders with line-item data\n4. Average order value\n5. Daily order volume\n6. Monthly revenue trend\n7. Revenue by pizza category\n8. Revenue by pizza size\n9. Top pizzas by revenue\n10. Top pizzas by quantity sold\n11. Orders by hour\n12. Category revenue contribution (%)\n13. Day-of-week order pattern\n14. Highest-value orders\n\n## 🔍 Data Quality Finding\n\nThe supplied dump contains **21,350 rows in `orders`**, **40,856 rows in `order_details`**, **32 pizza types**, and **96 pizza-size variants**. The available order-detail data covers **17,997 distinct order IDs**, so the project deliberately includes data-quality checks rather than silently assuming every order has sales-detail records.\n\nThis is an important analytical practice: **validate the source data before presenting KPIs.**\n\n## 📁 Project Structure\n\n```text\npizza_hutt/\n├── README.md\n├── database/\n│   ├── 01_schema.sql\n│   └── 02_load_data.sql\n├── sql/\n│   ├── 01_data_quality_checks.sql\n│   └── 02_business_analysis.sql\n├── screenshots/\n└── data/\n```\n\n## ▶️ How to Run\n\n1. Open MySQL Workbench.\n2. Run `database/01_schema.sql`.\n3. Run `database/02_load_data.sql`.\n4. Run `sql/01_data_quality_checks.sql`.\n5. Run `sql/02_business_analysis.sql`.\n6. Save useful result screenshots in `screenshots/`.\n\n## 💼 Resume Description\n\n**Pizza Hut Sales Analysis | MySQL**  \nBuilt a relational SQL analysis project using MySQL to evaluate pizza sales performance. Used multi-table joins, aggregations, date/time functions, subqueries, KPI calculations, product/category analysis, and data-quality validation to derive business insights from transactional data.\n\n## 👤 Author\n\n**Bhavishya**  \nData Analytics Portfolio Project\n'''
(root/'README.md').write_text(readme)
(root/'.gitignore').write_text('*.log\n.DS_Store\nThumbs.db\n.vscode/\n')
(root/'screenshots'/'README.md').write_text('# Screenshots\n\nAdd screenshots of important MySQL query results here, such as KPI output, monthly revenue, category revenue and top-10 pizzas.\n')
(root/'data'/'README.md').write_text('# Data\n\nThe source data is included in `database/02_load_data.sql`. No separate CSV is required to reproduce the MySQL analysis.\n')
# Keep the exact original dump as an optional archive for traceability.
shutil.copy2(root/'Dump20260919.sql', root/'database'/'Dump20260919_original.sql')
(root/'Dump20260919.sql').unlink()

zip_path=Path('/mnt/data/pizza_hutt_mysql_portfolio.zip')
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED) as z:
    for f in root.rglob('*'):
        if f.is_file(): z.write(f, Path('pizza_hutt')/f.relative_to(root))
print(zip_path)
